def drive(me, enemy, arena):
    # Simple proportional steering towards the enemy
    bearing = bearing_to(enemy.x, enemy.y)  # degrees left (+) / right (-)
    if abs(bearing) < 10:
        # go straight ahead
        return (1.0, 1.0)
    if bearing > 0:
        # enemy on our left → turn left
        return (1.0, -1.0)
    else:
        # enemy on our right → turn right
        return (-1.0, 1.0)

