def drive(me, enemy, arena):
    # Aim roughly toward the enemy and drive forward.
    bearing = bearing_to(enemy.x, enemy.y)  # degrees left (+) / right (-)
    # If we are roughly aligned, go forward.
    if abs(bearing) < 10:
        return (1.0, 1.0)
    # Turn toward the enemy.
    if bearing > 0:
        return (1.0, -1.0)   # left turn
    else:
        return (-1.0, 1.0)   # right turn

def weapons(me, enemy, arena):
    # Spin both spinners at their maximum safe speed.
    cmds = []
    if me.weapons.get("front", {}).get("health", 0) > 0:
        cmds.append(spin("front", 5000))
    if me.weapons.get("right", {}).get("health", 0) > 0:
        cmds.append(spin("right", 5000))
    return cmds if cmds else None
